const staticData = $getWorkflowStaticData('global');
if (!staticData.zabbix_incidents) staticData.zabbix_incidents = {};

const input = $input.first().json.body || $input.first().json;
const rawHost = input.host || input.hostname || input.device || 'Desconocido';
const eventStatus = String(input.status || input.event_status || input.value || 'PROBLEM').toUpperCase();
const severity = input.severity || input.trigger_severity || 'High';
const problemName = input.event_name || input.trigger_name || input.problem || input.message || 'Sin descripción';
const eventDate = input.event_date || input.eventDate || new Date().toISOString().split('T')[0];
const eventTime = input.event_time || input.eventTime || new Date().toISOString().split('T')[1].substring(0,8);
const source = input.source || input.origen || 'Zabbix35';

// Normalización para deduplicación cruzada Zabbix 35 / Zabbix 20
function normalizeHost(h) {
  if (!h) return 'unknown';
  let s = String(h).toLowerCase().trim();
  s = s.replace(/\.(noc-admin|local|lan|internal).*$/, '');
  s = s.replace(/[-_]+/g, '_');
  return s;
}

function normalizeProblem(p) {
  if (!p) return 'general';
  let s = String(p).toLowerCase().trim();
  if (s.includes('icmp') || s.includes('ping')) return 'icmp_ping';
  if (s.includes('link down') || s.includes('interface down') || s.includes('operstatus down')) return 'link_down';
  if (s.includes('bgp') || s.includes('peer')) return 'bgp_down';
  if (s.includes('high memory') || s.includes('memoria')) return 'high_memory';
  if (s.includes('high cpu') || s.includes('cpu')) return 'high_cpu';
  if (s.includes('power') || s.includes('fuente')) return 'power_issue';
  return s.replace(/[^a-z0-9]/g, '_').substring(0, 40);
}

const normHost = normalizeHost(rawHost);
const normProb = normalizeProblem(problemName);
const dedupKey = `${normHost}::${normProb}`;

const isProblem = ['PROBLEM', 'DOWN', 'FALLA', '1'].includes(eventStatus);
const normStatus = isProblem ? 'PROBLEM' : 'RESOLVED';

const prev = staticData.zabbix_incidents[dedupKey] || {};

// Si es un PROBLEM repetido mientras ya está activo el episodio, actualizar fuentes y descartar duplicado
if (isProblem && prev.status === 'PROBLEM') {
  let sources = Array.isArray(prev.sources) ? [...prev.sources] : [prev.source || 'Zabbix35'];
  if (!sources.includes(source)) sources.push(source);
  staticData.zabbix_incidents[dedupKey] = {
    ...prev,
    sources,
    updated_at: new Date().toISOString()
  };
  return []; // Descarte silencioso de duplicado
}

// Si es una recuperación repetida cuando ya está marcado como RESOLVED, descartar duplicado
if (!isProblem && (prev.status === 'RESOLVED' || !prev.status)) {
  return [];
}

let downSeq = prev.down_seq || 0;
let alertSent = prev.alert_sent || false;
let sources = Array.isArray(prev.sources) ? [...prev.sources] : [];
if (!sources.includes(source)) sources.push(source);

if (isProblem) {
  downSeq += 1;
  alertSent = false;
  sources = [source];
}

staticData.zabbix_incidents[dedupKey] = {
  ...prev,
  host: rawHost,
  dedup_key: dedupKey,
  status: normStatus,
  severity,
  problem: problemName,
  sources,
  down_seq: downSeq,
  alert_sent: alertSent,
  updated_at: new Date().toISOString(),
  event_date: eventDate,
  event_time: eventTime
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:11440/alerts/record',
    body: {
      source: source || 'Zabbix',
      host: rawHost,
      problem: problemName,
      status: normStatus,
      severity: severity
    },
    json: true
  });
} catch(e) {}

if (!staticData.zabbix_devices) staticData.zabbix_devices = {};
staticData.zabbix_devices[rawHost] = {
  host: rawHost,
  status: normStatus,
  severity,
  problem: problemName,
  last_updated: new Date().toISOString()
};

return [{
  json: {
    host: rawHost,
    status: normStatus,
    is_problem: isProblem,
    severity,
    problem: problemName,
    eventDate,
    eventTime,
    source,
    sources: sources.join(', '),
    dedup_key: dedupKey,
    down_seq: downSeq
  }
}];

const input = $input.first().json;
const host = input.host || 'Desconocido';
const problem = input.problem || 'Sin descripción';
const severity = input.severity || 'No clasificada';
const status = input.status || (input.send_alert ? 'PROBLEM' : 'RESOLVED');
const sources = input.sources || input.source || 'Zabbix';
const eventDate = input.eventDate || new Date().toISOString().split('T')[0];
const eventTime = input.eventTime || new Date().toISOString().split('T')[1].substring(0,8);

let prompt = '';
if (status === 'PROBLEM') {
  prompt = `Eres OpenClaw, analista experto de operaciones de red (NOC) de noc-admin.
Alerta sostenida de Zabbix confirmada tras 5 minutos sin recuperación:
- Equipo: ${host}
- Problema: ${problem}
- Severidad: ${severity}
- Sistema(s) de detección: ${sources}
- Hora inicio: ${eventDate} ${eventTime}

Proporciona un diagnóstico técnico y conciso en español (máximo 4 líneas):
1. Diagnóstico e impacto real en la red o servicio.
2. Causa probable.
3. Acción inmediata recomendada para el operador.
Sé profesional, técnico y directo.`;
} else {
  prompt = `Eres OpenClaw, analista experto de operaciones de red (NOC) de noc-admin.
El siguiente equipo/servicio de Zabbix se ha RECUPERADO y restablecido:
- Equipo: ${host}
- Problema resuelto: ${problem}
- Severidad previa: ${severity}
- Sistema(s): ${sources}
- Hora recuperación: ${input.recovered_at || eventTime}

Proporciona una confirmación de recuperación breve en español (máximo 2 líneas):
1. Confirmación de restablecimiento del servicio.
2. Recomendación de verificación final.`;
}

return [{
  json: {
    ...input,
    host,
    severity,
    sources,
    status,
    eventDate,
    eventTime,
    ollama_payload: {
      model: "agent.fast",
      messages: [
        {
          role: "system",
          content: "Eres OpenClaw, analista experto del NOC noc-admin. Respondes en español, conciso y técnico. Máximo 4 líneas."
        },
        {
          role: "user",
          content: prompt
        }
      ],
      stream: false
    }
  }
}];

