const staticData = $getWorkflowStaticData('global');
if (!staticData.devices) staticData.devices = {};
const input = $input.first().json.body || $input.first().json;
const deviceName = input.device || input.name || input.hostname || 'Desconocido';
const currentStatus = input.status || input.event_status || 'DOWN';
const upperName = deviceName.toUpperCase();
const isSwitch = upperName.startsWith('SW_');
const isMikrotik = upperName.startsWith('MK_');
const isCriticalWord = ['BEQUANT', 'OLT', 'CORE', 'BACKBONE'].some(w => upperName.includes(w));
const isImportant = isSwitch || isMikrotik || isCriticalWord;

const prev = staticData.devices[deviceName] || {};
let downSeq = prev.down_seq || 0;
let alertSent = prev.alert_sent;
if (String(currentStatus).toUpperCase() === 'DOWN' && String(prev.status || '').toUpperCase() !== 'DOWN') {
  downSeq += 1;
  alertSent = false;
}

staticData.devices[deviceName] = { ...prev, name: deviceName, status: currentStatus, is_important: isImportant, updated_at: new Date().toISOString(), down_seq: downSeq, alert_sent: alertSent };

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:11440/alerts/record',
    body: {
      source: 'TheDude',
      host: deviceName,
      problem: input.problem || input.service || 'Dispositivo o servicio caído',
      status: currentStatus,
      severity: isImportant ? 'Alta' : 'Advertencia'
    },
    json: true
  });
} catch(e) {}

return [{ json: { ...input, device: deviceName, status: currentStatus, is_important: isImportant, down_seq: downSeq } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.devices) staticData.devices = {};
const inputData = $input.first().json;
const deviceName = inputData.device || inputData.host || 'UNKNOWN';
const deviceRecord = staticData.devices[deviceName] || {};
const currentStatus = String(deviceRecord.status || inputData.status || '').toUpperCase();
const isImportant = deviceRecord.is_important !== undefined ? deviceRecord.is_important : true;

const seqOk = inputData.down_seq === undefined || deviceRecord.down_seq === inputData.down_seq;
const notYetAlerted = deviceRecord.alert_sent !== true;
const sendAlert = (currentStatus === 'DOWN') && isImportant && seqOk && notYetAlerted;

if (sendAlert) {
  staticData.devices[deviceName] = { ...deviceRecord, alert_sent: true };
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:11440/alerts/voice',
      body: {
        host: deviceName,
        problem: inputData.problem || 'Caída de equipo',
        severity: 'Alta',
        source: 'TheDude'
      },
      json: true
    });
  } catch(e) {}
}
return [{ json: { send_alert: sendAlert, device: deviceName, status: currentStatus, is_important: isImportant, details: staticData.devices[deviceName] || deviceRecord } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.devices) staticData.devices = {};
const inputData = $input.first().json;
const deviceName = inputData.device || inputData.host || 'UNKNOWN';

// NUEVO: a esta rama también llegan caídas de equipos NO importantes (salida falsa del IF).
// Eso no es una recuperación: se descarta sin tocar el estado.
if (String(inputData.status || '').toUpperCase() === 'DOWN') return [];

const deviceRecord = staticData.devices[deviceName] || {};
const isImportant = deviceRecord.is_important !== undefined ? deviceRecord.is_important : true;
// NUEVO: solo se avisa de la recuperación si se avisó de la caída.
// (alert_sent indefinido = estado anterior a este cambio: se trata como avisado)
const alertWasSent = deviceRecord.alert_sent === true;
staticData.devices[deviceName] = { ...deviceRecord, status: 'UP', last_up: new Date().toISOString(), alert_sent: false };
return [{ json: { send_recovery: isImportant && alertWasSent, device: deviceName, status: 'UP', is_important: isImportant, details: staticData.devices[deviceName] } }];

const input = $input.first().json;
const device = input.device || input.details?.device || 'UNKNOWN';
const status = input.status || (input.send_alert ? 'DOWN' : 'UP');
const upperName = device.toUpperCase();
let deviceType = 'equipo de red';
if (upperName.startsWith('SW_')) deviceType = 'switch de red';
else if (upperName.startsWith('MK_')) deviceType = 'router MikroTik';
else if (upperName.includes('OLT')) deviceType = 'OLT (fibra óptica)';
else if (upperName.includes('CORE') || upperName.includes('BACKBONE')) deviceType = 'equipo core/backbone (crítico)';
else if (upperName.includes('BEQUANT')) deviceType = 'dispositivo Bequant';

const prompt = `Eres OpenClaw, el analista de NOC. El ${deviceType} llamado ${device} acaba de pasar a estado ${status}. Proporciona un diagnóstico conciso en español con: 1) impacto probable en la red, 2) posible causa según el tipo de equipo, 3) acción recomendada inmediata. Máximo 4 líneas.`;

return [{
  json: {
    ...input,
    device,
    status,
    deviceType,
    ollama_payload: {
      model: "agent.fast",
      messages: [
        {
          role: "system",
          content: "Eres OpenClaw, analista experto del NOC. Respondes en español, de forma concisa. Máximo 4 líneas por respuesta."
        },
        {
          role: "user",
          content: prompt
        }
      ],
      stream: false
    }
  }
}];

let subs = [];
try {
  const subsRes = await this.helpers.httpRequest({
    method: "GET",
    url: "http://host.docker.internal:11440/subscribers",
    json: true
  });
  subs = Array.isArray(subsRes) ? subsRes : [];
} catch (e) {
  subs = [{ chat_id: "1558973693" }];
}

const inputItem = $input.first().json;
return subs.map(s => ({
  json: {
    ...inputItem,
    target_chat_id: String(s.chat_id)
  }
}));

let subs = [];
try {
  const subsRes = await this.helpers.httpRequest({
    method: "GET",
    url: "http://host.docker.internal:11440/subscribers",
    json: true
  });
  subs = Array.isArray(subsRes) ? subsRes : [];
} catch (e) {
  subs = [{ chat_id: "1558973693" }];
}

const inputItem = $input.first().json;
return subs.map(s => ({
  json: {
    ...inputItem,
    target_chat_id: String(s.chat_id)
  }
}));

const staticData = $getWorkflowStaticData('global');
if (!staticData.zabbix_incidents) staticData.zabbix_incidents = {};

const inputData = $input.first().json;
const dedupKey = inputData.dedup_key;
const inc = staticData.zabbix_incidents[dedupKey] || {};

const currentStatus = String(inc.status || inputData.status || '').toUpperCase();
const seqOk = (inputData.down_seq === undefined) || (inc.down_seq === inputData.down_seq);
const notYetAlerted = (inc.alert_sent !== true);

// Filtro inteligente de relevancia/severidad:
const sevStr = String(inc.severity || inputData.severity || '').toLowerCase();
const probStr = String(inc.problem || inputData.problem || '').toLowerCase();
const hostStr = String(inc.host || inputData.host || '').toLowerCase();

const isDisasterOrHigh = sevStr.includes('disaster') || sevStr.includes('high') || sevStr.includes('desastre') || sevStr.includes('alta') || sevStr === '4' || sevStr === '5';
const isCriticalKeyword = ['olt', 'core', 'mikrotik', 'mk_', 'sw_', 'switch', 'bgp', 'uplink', 'caida', 'offline', 'unavailable', 'ping', 'down'].some(k => hostStr.includes(k) || probStr.includes(k));
const isLowNoise = (sevStr.includes('information') || sevStr.includes('info') || sevStr.includes('warning') || sevStr === '1' || sevStr === '2') && !isCriticalKeyword;

const isWorthSending = (isDisasterOrHigh || isCriticalKeyword) && !isLowNoise;

// Solo avisa si sigue caído tras los 5 minutos, pertenece al mismo episodio, no fue alertado antes y vale la pena enviar
const sendAlert = (currentStatus === 'PROBLEM') && seqOk && notYetAlerted && isWorthSending;

if (sendAlert) {
  staticData.zabbix_incidents[dedupKey] = { ...inc, alert_sent: true };
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:11440/alerts/voice',
      body: {
        host: inc.host || inputData.host,
        problem: inc.problem || inputData.problem,
        severity: inc.severity || inputData.severity,
        source: 'Zabbix'
      },
      json: true
    });
  } catch(e) {}
}

return [{
  json: {
    ...inputData,
    send_alert: sendAlert,
    host: inc.host || inputData.host,
    severity: inc.severity || inputData.severity,
    problem: inc.problem || inputData.problem,
    sources: inc.sources ? inc.sources.join(', ') : (inputData.sources || 'Zabbix'),
    details: staticData.zabbix_incidents[dedupKey] || inc
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.zabbix_incidents) staticData.zabbix_incidents = {};

const inputData = $input.first().json;
const dedupKey = inputData.dedup_key;
const inc = staticData.zabbix_incidents[dedupKey] || {};

if (inputData.is_problem === true) return [];

// SOLO se avisa de la recuperación si previamente se envió la alerta de caída tras los 5 min
const alertWasSent = (inc.alert_sent === true);

staticData.zabbix_incidents[dedupKey] = {
  ...inc,
  status: 'RESOLVED',
  last_recovery: new Date().toISOString(),
  alert_sent: false
};

if (!staticData.zabbix_devices) staticData.zabbix_devices = {};
staticData.zabbix_devices[inputData.host] = {
  host: inputData.host,
  status: 'RESOLVED',
  severity: inc.severity || inputData.severity,
  problem: inc.problem || inputData.problem,
  last_updated: new Date().toISOString()
};

return [{
  json: {
    ...inputData,
    send_recovery: alertWasSent,
    status: 'RESOLVED',
    host: inc.host || inputData.host,
    severity: inc.severity || inputData.severity,
    problem: inc.problem || inputData.problem,
    sources: inc.sources ? inc.sources.join(', ') : (inputData.sources || 'Zabbix'),
    recovered_at: new Date().toLocaleTimeString('es-VE')
  }
}];

